<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import AppModal from '@/components/AppModal.vue'
import { demoMode, request as liveRequest } from '@/services/quality'
import { boardRequest } from '@/services/cdcBoardsDemo'
const request = demoMode ? boardRequest : liveRequest

interface ActionRow { id:number; title:string; description:string; status:string; priority:string; owner_id:number; due_date:string; version:number; overdue:boolean; sources:{source_type:string;label:string}[] }
interface PlanRow { id:number; reference:string; title:string; objective:string; status:string; starts_on:string; ends_on:string; owner_id:number; version:number }
interface Page { data: { data:ActionRow[]; current_page:number; last_page:number }; indicators:{overdue:number;by_status:Record<string,number>;definition:string;updated_at:string} }
const rows=ref<ActionRow[]>([]), indicators=ref<Page['indicators']>(), loading=ref(false), busy=ref(false), error=ref(''), notice=ref(''), modal=ref(false), detail=ref<ActionRow|null>(null)
const plans=ref<PlanRow[]>([]), canWrite=ref(false), canApprove=ref(false), planModal=ref(false), editingPlan=ref<PlanRow|null>(null)
const planForm=ref({title:'',objective:'',starts_on:'',ends_on:'',owner_id:0})
const form=ref({title:'',description:'',effectiveness_criteria:'',owner_id:0,due_date:'',priority:'normal',source_type:'finding',source_id:0,source_label:''})
let pendingRequestKey=''
watch(form,()=>{pendingRequestKey=''}, {deep:true})
const base='/qualite/actions-v2'
async function load(){loading.value=true;error.value='';try{const [result,planResult]=await Promise.all([request<Page>(`${base}?per_page=100`),request<{data:{data:PlanRow[]};can_write:boolean;can_approve:boolean}>(`${base}/plans`)]);rows.value=result.data.data;indicators.value=result.indicators;plans.value=planResult.data.data;canWrite.value=planResult.can_write;canApprove.value=planResult.can_approve}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function create(){form.value={title:'',description:'',effectiveness_criteria:'',owner_id:Number(sessionStorage.getItem('bestpharma.user_id')||0),due_date:'',priority:'normal',source_type:'finding',source_id:0,source_label:''};pendingRequestKey='';modal.value=true}
async function save(){busy.value=true;error.value='';try{pendingRequestKey ||= globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;await request(`${base}/actions`,'POST',{title:form.value.title,description:form.value.description,effectiveness_criteria:form.value.effectiveness_criteria,request_key:pendingRequestKey,owner_id:form.value.owner_id,due_date:form.value.due_date,priority:form.value.priority,sources:[{type:form.value.source_type,id:form.value.source_id||null,label:form.value.source_label}],confirmed:true});pendingRequestKey='';modal.value=false;notice.value='Action ajoutée au registre M4.';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function show(row:ActionRow){try{detail.value=(await request<{data:ActionRow}>(`${base}/actions/${row.id}`)).data}catch(e){error.value=(e as Error).message}}
function editPlan(plan?:PlanRow){editingPlan.value=plan||null;planForm.value=plan?{title:plan.title,objective:plan.objective,starts_on:plan.starts_on,ends_on:plan.ends_on,owner_id:plan.owner_id}:{title:'',objective:'',starts_on:'',ends_on:'',owner_id:Number(sessionStorage.getItem('bestpharma.user_id')||0)};planModal.value=true}
async function savePlan(){busy.value=true;error.value='';try{if(editingPlan.value)await request(`${base}/plans/${editingPlan.value.id}`,'PUT',{...planForm.value,version:editingPlan.value.version});else await request(`${base}/plans`,'POST',{...planForm.value,confirmed:true});planModal.value=false;notice.value='Plan M4 enregistré en brouillon.';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function planTransition(plan:PlanRow,action:'submit'|'decision',decision?:string){let reason='';if(decision==='request_changes'){reason=window.prompt('Motif des modifications attendues :')?.trim()||'';if(!reason)return}busy.value=true;error.value='';try{await request(`${base}/plans/${plan.id}/${action}`,'POST',{version:plan.version,confirmed:true,...(decision?{decision}:{}),...(reason?{reason}:{})});notice.value='État du plan mis à jour.';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function transition(row:ActionRow, action:string, extra:Record<string,unknown>={}){busy.value=true;error.value='';try{await request(`${base}/actions/${row.id}/${action}`,'POST',{version:row.version,confirmed:true,...extra});detail.value=null;notice.value='Transition enregistrée.';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>

<template><div class="page">
  <div class="page-heading compact"><div><p class="eyebrow">AMÉLIORATION CONTINUE</p><h1>Plans & actions</h1><p class="page-subtitle">Registre unique des actions, preuves documentaires versionnées et vérification d’efficacité.</p></div><button class="button primary" @click="create">Nouvelle action</button></div>
<p v-if="error" class="alert error" role="alert">{{error}} <button @click="load">Réessayer</button></p><p v-if="notice" class="alert success" role="status">{{notice}}</p>
  <div v-if="indicators" class="mini-stats"><span>{{rows.length}} <small>actions affichées</small></span><span>{{indicators.overdue}} <small>en retard</small></span><span>{{indicators.by_status.closed||0}} <small>clôturées</small></span></div>
  <section class="panel"><div class="panel-heading"><h2>Plans d’amélioration</h2><button v-if="canWrite" class="button secondary" @click="editPlan()">Créer un plan</button></div><p v-if="!plans.length" class="empty-state">Aucun plan M4 enregistré.</p><div v-for="plan in plans" :key="plan.id" class="document-row"><div><strong>{{plan.title}}</strong><p>{{plan.reference}} · {{plan.starts_on}} → {{plan.ends_on}} · {{plan.status}} · v{{plan.version}}</p><p>{{plan.objective}}</p></div><div class="heading-actions"><button v-if="canWrite && ['draft','changes_requested'].includes(plan.status)" class="button secondary small" @click="editPlan(plan)">Modifier</button><button v-if="canWrite && plan.status==='draft'" class="button primary small" @click="planTransition(plan,'submit')">Soumettre</button><button v-if="canApprove && plan.status==='submitted'" class="button primary small" @click="planTransition(plan,'decision','approve')">Approuver</button><button v-if="canApprove && plan.status==='submitted'" class="button secondary small" @click="planTransition(plan,'decision','request_changes')">Demander modification</button></div></div></section>
  <section class="panel"><div class="panel-heading"><h2>Registre des actions</h2><span v-if="indicators" class="muted-note">Calcul des retards : {{indicators.definition}}</span></div><p v-if="loading" role="status">Chargement…</p><div v-else-if="!rows.length" class="empty-state">Aucune action enregistrée. Les actions M2 approuvées peuvent être intégrées depuis la mission d’origine.</div>
    <div v-else class="table-scroll"><table><thead><tr><th>Action / source</th><th>Responsable</th><th>Échéance</th><th>Priorité</th><th>État</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><button class="table-title" @click="show(row)">{{row.title}}</button><small class="table-subtitle">{{row.sources.map(source=>source.label).join(' · ')}}</small></td><td>#{{row.owner_id}}</td><td :class="{'overdue-text':row.overdue}">{{row.due_date}}</td><td>{{row.priority}}</td><td>{{row.status}}</td></tr></tbody></table></div>
  </section><p class="muted-note">Aucune échéance réglementaire ou transmission ABMed n’est présumée. Les alertes email restent simulées avec Laravel log en local.</p>
  <AppModal v-model="modal" title="Créer une action M4" :busy="busy"><form id="m4-create" class="form-body" @submit.prevent="save"><label>Titre<input v-model="form.title" required maxlength="180"></label><label>Description<textarea v-model="form.description" required maxlength="5000" rows="4"></textarea></label><label>Critère d’efficacité attendu<textarea v-model="form.effectiveness_criteria" required minlength="8" maxlength="2000" rows="2" placeholder="Mesure à constater, sans seuil réglementaire présumé"></textarea></label><div class="form-grid"><label>Responsable (ID membre)<input v-model.number="form.owner_id" type="number" min="1" required></label><label>Échéance<input v-model="form.due_date" type="date" required></label><label>Priorité<select v-model="form.priority"><option value="low">Basse</option><option value="normal">Normale</option><option value="high">Haute</option></select></label><label>Source<select v-model="form.source_type"><option value="finding">Constat M2 partagé</option><option value="mission">Mission M2</option><option value="document">Document M3</option><option value="risk">Risque (référence descriptive)</option><option value="complaint">Réclamation (référence descriptive)</option></select></label><label v-if="form.source_type==='finding'||form.source_type==='mission'||form.source_type==='document'">ID source<input v-model.number="form.source_id" type="number" min="1" required></label><label>Libellé de source<input v-model="form.source_label" :required="['risk','complaint'].includes(form.source_type)" maxlength="220" placeholder="Facultatif si source vérifiable"></label></div><p class="muted-note">Un lien vers M2/M3 est vérifié côté serveur et n’en duplique pas le contenu.</p></form><template #footer><button class="button secondary" :disabled="busy" @click="modal=false">Annuler</button><button class="button primary" type="submit" form="m4-create" :disabled="busy">Créer l’action</button></template></AppModal>
  <AppModal v-model="planModal" :title="editingPlan?'Réviser le plan M4':'Créer un plan M4'" :busy="busy"><form id="m4-plan" class="form-body" @submit.prevent="savePlan"><label>Titre<input v-model="planForm.title" required maxlength="180"></label><label>Objectif<textarea v-model="planForm.objective" required maxlength="5000" rows="4"></textarea></label><div class="form-grid"><label>Début<input v-model="planForm.starts_on" type="date" required></label><label>Fin<input v-model="planForm.ends_on" type="date" required></label><label>Responsable (ID membre)<input v-model.number="planForm.owner_id" type="number" min="1" required></label></div></form><template #footer><button class="button secondary" :disabled="busy" @click="planModal=false">Annuler</button><button class="button primary" type="submit" form="m4-plan" :disabled="busy">Enregistrer le brouillon</button></template></AppModal>
  <AppModal :model-value="!!detail" title="Détail et workflow M4" size="wide" @update:model-value="detail=null"><div v-if="detail" class="form-body"><h3>{{detail.title}}</h3><p>{{detail.description}}</p><p>Échéance : {{detail.due_date}} · état {{detail.status}} · version {{detail.version}}</p><ul><li v-for="source in detail.sources" :key="source.source_type+source.label">{{source.source_type}} — {{source.label}}</li></ul><section class="panel"><h4>Historique</h4><p v-for="event in (detail as any).events||[]" :key="event.id">{{event.event}} · {{event.created_at}}</p></section><div class="heading-actions"><button v-if="detail.status==='open'" class="button secondary" :disabled="busy" @click="transition(detail,'start')">Démarrer</button><button v-if="['open','in_progress'].includes(detail.status)" class="button secondary" :disabled="busy" @click="transition(detail,'complete')">Marquer réalisée</button><button v-if="detail.status==='completed'" class="button primary" :disabled="busy" @click="transition(detail,'verify',{decision:'accept'})">Vérifier</button></div><p class="muted-note">L’ajout d’une preuve M3 et la revue d’efficacité sont disponibles par API; la clôture les exige.</p></div></AppModal>
</div></template>
